'use client';
// "Ask the data": AI narrative generated by the backend LLM pipeline (DeepSeek) from read-only tools over the
// warehouse. Numbers the backend could not match to the data are flagged. Drafted with AI assistance (Claude Code).
import { useState } from 'react';
import { Sparkles } from 'lucide-react';

import { useNarrative } from '@/lib/liveLayers';

const NUM = /([-−+]?\d+(?:\.\d+)?)/g;

/** The narrative with numbers highlighted: teal = matched to the data, coral = could not be verified. */
export function NarrativeText({ data, className = '' }) {
  const bad = new Set(data.unverified_numbers || []);
  const parts = data.text.split(NUM);
  return (
    <p className={`whitespace-pre-line ${className}`}>
      {parts.map((part, i) =>
        i % 2 === 1 && /\d\.\d|\d%|^\d{2,}$/.test(part + (parts[i + 1] || '').slice(0, 1)) ? (
          <mark
            key={i}
            title={bad.has(part) ? 'Not found in the data returned to the model' : 'Matches the analysis data'}
            className={`rounded px-0.5 font-semibold text-inherit ${bad.has(part) ? 'bg-[#FF7A6B]/30 underline decoration-wavy' : 'bg-[#4FB3A9]/25'}`}
          >
            {part}
          </mark>
        ) : (
          <span key={i}>{part}</span>
        )
      )}
    </p>
  );
}

export function NarrativePanel({ investigation }) {
  const { state, generate } = useNarrative(investigation);
  const [question, setQuestion] = useState('');
  const data = state.data;
  const busy = state.status === 'loading';
  return (
    <section className="rounded-[22px] bg-[#FBFAF6] border border-[#E6E0D2] p-5 space-y-3 print:hidden">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <div className="font-mono text-[10px] uppercase tracking-wider text-[#5B6478]">ASK THE DATA · AI NARRATIVE</div>
          <p className="text-[13px] text-[#5B6478]">
            An LLM reads this investigation&apos;s results and the warehouse through read-only tools; every number it writes is checked.
          </p>
        </div>
      </div>
      <div className="flex flex-col sm:flex-row gap-2">
        <input
          value={question}
          maxLength={500}
          onChange={(e) => setQuestion(e.target.value)}
          placeholder="Optional question, e.g. Which variables move with the rain, and how sure are we?"
          className="flex-1 rounded-full bg-white border border-[#E6E0D2] px-4 py-2.5 text-[13px] text-[#131D38] focus:outline-none focus:border-[#131D38]"
        />
        <button
          type="button"
          disabled={busy}
          onClick={() => generate(question)}
          className="inline-flex items-center justify-center gap-2 px-5 py-2.5 rounded-full bg-[#131D38] text-[#f4f1ea] text-[13px] font-semibold hover:bg-[#1E2B52] disabled:opacity-50 cursor-pointer"
        >
          <Sparkles className="w-4 h-4 text-[#ffc20d]" />
          {busy ? 'Writing…' : data ? 'Regenerate' : 'Generate narrative'}
        </button>
      </div>

      {state.status === 'error' && (
        <p className="text-[13px] text-[#991B1B]">
          {state.error?.message || 'The narrative could not be generated.'}
          {state.error?.requestId ? ` (request ${state.error.requestId})` : ''}
        </p>
      )}

      {data && (
        <div className="rounded-[18px] bg-white border border-[#E6E0D2] p-4 space-y-2">
          <NarrativeText data={data} className="text-[14px] leading-[1.7] text-[#131D38]" />
          <div className="flex flex-wrap gap-2 pt-2 border-t border-[#E6E0D2] font-mono text-[10px]">
            <span className="px-2 py-0.5 rounded-full bg-[#131D38] text-[#ffc20d]">AI-generated · {data.model}</span>
            <span className={`px-2 py-0.5 rounded-full ${data.verified ? 'bg-[#4FB3A9]/20 text-[#0f5d56]' : 'bg-[#FF7A6B]/20 text-[#991B1B]'}`}>
              {data.verified ? 'All numbers match the data' : `${data.unverified_numbers.length} number(s) not found in the data`}
            </span>
            <span className="px-2 py-0.5 rounded-full bg-[#f4f1ea] text-[#5B6478]">tools: {[...new Set(data.tools_used)].join(', ')}</span>
            {data.cached && <span className="px-2 py-0.5 rounded-full bg-[#f4f1ea] text-[#5B6478]">cached</span>}
          </div>
          <p className="text-[11px] text-[#5B6478]">{data.ai_label}</p>
        </div>
      )}
    </section>
  );
}
